package run.ikaros.finance; import java.time.Instant; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; import run.ikaros.common.ConflictException; import run.ikaros.common.NotFoundException; @Service public class LedgerMemberService{private final LedgerRepository ledgers;private final LedgerMemberRepository members;public LedgerMemberService(LedgerRepository l,LedgerMemberRepository m){ledgers=l;members=m;}public Mono<LedgerMemberView> add(UUID a,UUID l,AddLedgerMemberRequest q){return owner(a,l).flatMap(x->members.findByLedgerIdAndPrincipalId(l,q.principalId()).flatMap(old->members.save(new LedgerMemberEntity(old.id(),l,q.principalId(),a,q.role(),old.createdAt(),old.version()))).switchIfEmpty(members.save(new LedgerMemberEntity(null,l,q.principalId(),a,q.role(),Instant.now(),null)))).map(this::view);}public Flux<LedgerMemberView> list(UUID a,UUID l){return owner(a,l).flatMapMany(x->members.findAllByLedgerIdOrderByCreatedAtAsc(l).map(this::view));}public Mono<Void> remove(UUID a,UUID l,UUID p){return owner(a,l).flatMap(x->{if(x.ownerId().equals(p))return Mono.error(new ConflictException("Ledger Owner 不能被移除"));return members.findByLedgerIdAndPrincipalId(l,p).switchIfEmpty(Mono.error(new NotFoundException("Ledger Member 不存在"))).flatMap(members::delete);}).then();}private Mono<LedgerEntity> owner(UUID a,UUID l){return ledgers.findById(l).filter(x->x.ownerId().equals(a)).switchIfEmpty(Mono.error(new NotFoundException("Ledger 不存在或无权管理成员")));}private LedgerMemberView view(LedgerMemberEntity x){return new LedgerMemberView(x.id(),x.ledgerId(),x.principalId(),x.role(),x.createdAt());}}
